using System.Collections.Concurrent;
using System.Runtime.CompilerServices;
using System.Text.Json;

namespace CombatSolver;

internal static class TaskHpDominanceObservation
{
    private const int Limit = 2_000_000;
    private static int NextId;
    private sealed class Counts
    {
        internal readonly int Id = Interlocked.Increment(ref NextId);
        internal readonly Dictionary<StateFingerprint, StateFingerprint> First = new();
        internal long Calls, Changed, RawDuplicate, ProjectedDifferentRaw, LimitBypass, PositiveHpCalls;
        internal int MaxHp;
        internal readonly List<object> Samples = new();
    }
    private static readonly ConditionalWeakTable<CombatBeamSolver, Counts> SolverCounts = new();
    private static readonly ConcurrentBag<Counts> AllCounts = new();
    private static readonly Counts AcrossSolvers = new();
    private static readonly Dictionary<StateFingerprint, StateFingerprint> RawProjections = new();
    private static long ProjectionConflicts;
    private static readonly Dictionary<StateFingerprint, int> RawHp = new();
    internal static int Hp(StateFingerprint raw) { lock (AcrossSolvers) return RawHp[raw]; }

    internal static bool TryProjection(StateFingerprint raw, out StateFingerprint projected)
    {
        lock (AcrossSolvers) return RawProjections.TryGetValue(raw, out projected);
    }

    static TaskHpDominanceObservation()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            string directory = Environment.GetEnvironmentVariable("TASK_HP_DOMINANCE_OUT")
                ?? throw new InvalidOperationException("Missing task observation output directory.");
            File.WriteAllText(Path.Combine(directory, "all-members.json"), JsonSerializer.Serialize(new {
                PerSolver = AllCounts.Select(Capture).ToArray(),
                AcrossSolvers = Capture(AcrossSolvers),
                Admissions = CombatBeamSolver.TaskHpAdmissionSummary(),
                ProjectionConflicts,
                Limit
            }));
        };
    }
    private static object Capture(Counts c)
    {
        lock (c) return new {
            c.Id, c.Calls, c.Changed, c.RawDuplicate, c.ProjectedDifferentRaw, c.LimitBypass,
            c.PositiveHpCalls, c.MaxHp, ProjectedKeys = c.First.Count, Samples = c.Samples.ToArray()
        };
    }
    internal static void Record(CombatBeamSolver solver, StateFingerprint raw,
        StateFingerprint projected, int turn, int hp)
    {
        Counts c = SolverCounts.GetValue(solver, static _ => {
            Counts created = new(); AllCounts.Add(created); return created;
        });
        RecordInto(c, raw, projected, turn, hp);
        RecordInto(AcrossSolvers, raw, projected, turn, hp);
        lock (AcrossSolvers)
        {
            if (RawProjections.TryGetValue(raw, out StateFingerprint previous))
            {
                if (previous != projected) ProjectionConflicts++;
            }
            else if (RawProjections.Count < Limit) RawProjections.Add(raw, projected);
            if (RawHp.TryGetValue(raw, out int previousHp)) { if (previousHp != hp) ProjectionConflicts++; }
            else if (RawHp.Count < Limit) RawHp.Add(raw, hp);
        }
    }
    private static void RecordInto(Counts c, StateFingerprint raw,
        StateFingerprint projected, int turn, int hp)
    {
        lock (c)
        {
            c.Calls++;
            if (raw != projected) c.Changed++;
            if (hp > 0) c.PositiveHpCalls++;
            c.MaxHp = Math.Max(c.MaxHp, hp);
            if (c.First.TryGetValue(projected, out StateFingerprint previous))
            {
                if (previous == raw) c.RawDuplicate++;
                else
                {
                    c.ProjectedDifferentRaw++;
                    if (c.Samples.Count < 8)
                        c.Samples.Add(new { turn, hp, raw, projected, previous });
                }
            }
            else if (c.First.Count < Limit) c.First.Add(projected, raw);
            else c.LimitBypass++;
        }
    }
}

