using System.Collections.Concurrent;
using System.Runtime.CompilerServices;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    private sealed class TaskHpAdmissionCounts(bool expansion)
    {
        internal readonly bool Expansion = expansion;
        internal long Calls, OriginalAccepted, LeaseOrDisabled, MissingProjection, SeedMissingProjection,
            NotStored, CrossRawMatch, DominatedByOtherRaw, GroupLimitBypass;
        internal readonly List<object> Samples = new();
    }
    private sealed class TaskHpAdmissionGroups(TaskHpAdmissionCounts counts)
    {
        internal readonly TaskHpAdmissionCounts Counts = counts;
        internal readonly Dictionary<StateFingerprint, HashSet<StateFingerprint>> Groups = new();
    }
    private static readonly ConditionalWeakTable<Dictionary<StateFingerprint, TranspositionFrontier>,
        TaskHpAdmissionGroups> TaskTables = new();
    private static readonly ConcurrentBag<TaskHpAdmissionCounts> TaskHpAdmissionAll = new();

    internal static object TaskHpAdmissionSummary() => TaskHpAdmissionAll.Select(c => new {
        c.Expansion, c.Calls, c.OriginalAccepted, c.LeaseOrDisabled, c.MissingProjection,
        c.SeedMissingProjection, c.NotStored, c.CrossRawMatch, c.DominatedByOtherRaw,
        c.GroupLimitBypass, Samples = c.Samples.ToArray()
    }).ToArray();

    private void TaskObserveHpAdmission(SearchNode node, bool accepted, bool expansion)
    {
        var actual = expansion ? _run.ExpandedTranspositions : _run.Transpositions;
        TaskHpAdmissionGroups groups = TaskTables.GetValue(actual, table => {
            TaskHpAdmissionCounts created = new(expansion); TaskHpAdmissionAll.Add(created);
            TaskHpAdmissionGroups result = new(created);
            foreach (StateFingerprint raw in table.Keys)
                if (TaskHpDominanceObservation.TryProjection(raw, out StateFingerprint projected))
                    TaskRegisterGroup(result, projected, raw);
                else created.SeedMissingProjection++;
            return result;
        });
        TaskHpAdmissionCounts c = groups.Counts;
        c.Calls++;
        if (!accepted) return;
        c.OriginalAccepted++;
        if ((expansion ? HasCycleExpansionTranspositionLease(node) : HasCycleAdmissionTranspositionLease(node))
            || CanRetainOrderedMutationLease(_run, node)
            || (policy.TranspositionPruningDisabledMask & (expansion ? 2 : 1)) != 0)
        { c.LeaseOrDisabled++; return; }
        if (!actual.ContainsKey(node.StateKey)) { c.NotStored++; return; }
        if (!TaskHpDominanceObservation.TryProjection(node.StateKey, out StateFingerprint projectedKey))
        { c.MissingProjection++; return; }
        if (groups.Groups.TryGetValue(projectedKey, out HashSet<StateFingerprint>? otherKeys))
        {
            TranspositionLabel next = new(node.PotionCount, node.PotionStrategicCost, node.FutureSoldHp,
                node.Snapshot.CumulativePlayerHpLost, node.ActionCount, node.Score);
            bool foundOther = false;
            foreach (StateFingerprint other in otherKeys)
            {
                if (other == node.StateKey || !actual.TryGetValue(other, out TranspositionFrontier? frontier))
                    continue;
                foundOther = true;
                if (TaskHpDominanceObservation.Hp(other) <= node.Snapshot.ProjectedPlayerHp || !frontier.TaskHpDominates(next)) continue;
                c.DominatedByOtherRaw++;
                if (c.Samples.Count < 8) c.Samples.Add(new {
                    node.Turn, node.ActionCount, node.PotionCount, node.PotionStrategicCost,
                    node.FutureSoldHp, node.Snapshot.CumulativePlayerHpLost, node.Score,
                    Hp = node.Snapshot.ProjectedPlayerHp, OtherHp = TaskHpDominanceObservation.Hp(other),
                    Raw = node.StateKey, Other = other, Projected = projectedKey
                });
                break;
            }
            if (foundOther) c.CrossRawMatch++;
        }
        TaskRegisterGroup(groups, projectedKey, node.StateKey);
    }
    private static void TaskRegisterGroup(TaskHpAdmissionGroups groups, StateFingerprint projected, StateFingerprint raw)
    {
        if (!groups.Groups.TryGetValue(projected, out HashSet<StateFingerprint>? members))
        {
            if (groups.Groups.Count >= 2_000_000) { groups.Counts.GroupLimitBypass++; return; }
            groups.Groups.Add(projected, members = new());
        }
        members.Add(raw);
    }
}

